	/*** PHP postSaveHook Method ***/

Factory::getApplication()->enqueueMessage("Spedizione mail", 'info');
$id = $model->getState($this->getName() . '.id');
// Print the Reservation confirmation and send the e-mail


// Salva l'ID nella sessione dell'utente
$session = Factory::getSession();
$session->set('last_saved_trip_id', $id);
//$this->setRedirect(Route::_('index.php?option=com_bookings&view=reservation_confirmation', false));

// COPY IN PRESENCE TABLE
// $validData is provided by JCB in this hook
// \Joomla\CMS\Factory::getApplication()->enqueueMessage('<pre>' . print_r($validData, true) . '</pre>', 'notice');
$db = \Joomla\CMS\Factory::getDbo();

// find the existing presence row for this id_code (0 = none yet, first save creates it)
$query = $db->getQuery(true)
    ->select($db->quoteName('id'))
    ->from($db->quoteName('#__bookings_presence'))
    ->where($db->quoteName('id_code') . ' = ' . $db->quote($validData['id_code']));
$db->setQuery($query);
$presenceId = (int) $db->loadResult();

// boot the presence admin model
$component   = \Joomla\CMS\Factory::getApplication()->bootComponent('com_bookings'); // adjust component name
$mvcFactory  = $component->getMVCFactory();
$presenceModel = $mvcFactory->createModel('Presence', 'Administrator', ['ignore_request' => true]);

$data = [
    'id'            => $presenceId,
    'id_code'       => $validData['id_code'],
    'group_name'    => $validData['group_name'],
    'participants'  => $validData['participants'],
    'datefirststop' => $validData['datefirststop'],
    'published'     => 1,
];
for ($i = 1; $i <= 10; $i++)
{
    $field = 'stop_' . sprintf('%02d', $i);
    $data[$field] = $validData[$field];
}

if (!$presenceModel->save($data))
{
    \Joomla\CMS\Factory::getApplication()->enqueueMessage($presenceModel->getError(), 'warning');
}

